src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (1, 1), (1, -1)]

    def score(dr, dc):
        return sum(
            grid[r][c] != 0
            and 0 <= r + dr < h
            and 0 <= c + dc < w
            and grid[r + dr][c + dc] != 0
            for r in range(h)
            for c in range(w)
        )

    direction = max(directions, key=lambda d: score(*d))
    dr, dc = direction

    def track_key(r, c):
        if direction == (0, 1):
            return r
        if direction == (1, 0):
            return c
        if direction == (1, 1):
            return c - r
        return c + r

    tracks = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                tracks.setdefault(track_key(r, c), set()).add(grid[r][c])

    period = len(tracks)
    colors = {}
    for key, values in tracks.items():
        if len(values) != 1:
            return None
        residue = key % period
        color = next(iter(values))
        if residue in colors and colors[residue] != color:
            return None
        colors[residue] = color

    if len(colors) != period:
        return None
    return [[colors[track_key(r, c) % period] for c in range(w)] for r in range(h)]
